import PackageDescription

// SCE Mesh for Swift hosts: the standard Mesh documents generated from `sce:std/mesh`
// (Sources/SceMesh/Generated, committed, regenerated by generate.sh and held to its sources by
// sce-build's drift test), and the router core that applies them. Transport-free: bytes and the
// clock come from the host (SCE_MESH.md §mesh-6.4). The Swift twin of backends/kotlin/mesh and
// backends/rust/mesh.
//
// The generated rules and codec call into the forge runtime; the core meets the engine through
// the statechart runtime's host-processor surface. The same platforms as both.
let package = Package(
    name: "SceMesh",
    platforms: [.macOS(.v15), .iOS(.v18)],
    products: [
        .library(name: "SceMesh", targets: ["SceMesh"]),
        // A Zenoh router in memory, and the clients' side of what the Zenoh binding (§mesh-20) needs of one:
        // what a real client's tests run against, apart from the core so no host links it in.
        .library(name: "SceMeshZenohKit", targets: ["SceMeshZenohKit"]),
    ],
    dependencies: [
        .package(path: "../runtime"),
        .package(path: "../forge-runtime"),
    ],
    targets: [
        .target(
            name: "SceMesh",
            dependencies: [
                .product(name: "SceRuntime", package: "runtime"),
                .product(name: "SceForgeRuntime", package: "forge-runtime"),
            ]
        ),
        .target(
            name: "SceMeshZenohKit",
            dependencies: ["SceMesh"]
        ),
        .testTarget(
            name: "SceMeshTests",
            dependencies: [
                "SceMesh",
                "SceMeshZenohKit",
                .product(name: "SceRuntime", package: "runtime"),
                .product(name: "SceForgeRuntime", package: "forge-runtime"),
            ]
        ),
    ]
)
